package com.thangit.boardinghouse.service;
import static org.assertj.core.api.Assertions.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.service.CheckoutSettlementService.*;
import com.thangit.boardinghouse.dto.request.lifecycle.RentalLifecycleRequests.RequestCheckout;
import java.time.*;
import java.util.*;
import java.math.BigDecimal;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
@EnabledIfSystemProperty(named="checkouts.workspace.mysql",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class CheckoutWorkspaceMysqlTest {
 final CheckoutSettlementMysqlTest b=new CheckoutSettlementMysqlTest();final DepositLedgerMysqlTest f=b.f;
 CheckoutWorkspaceService service;CheckoutEvidenceService files;CheckoutSettlementMysqlTest.Case a;
 final AuthenticatedUser manager=new AuthenticatedUser(2L,"manager",RoleCode.MANAGER),other=new AuthenticatedUser(4L,"owner-other",RoleCode.OWNER);
 @BeforeAll void setup()throws Exception{b.setup();service=new CheckoutWorkspaceService(f.db);files=new CheckoutEvidenceService(f.db,new RoomLifecycleGuard(f.db));}
 @BeforeEach void fixture(){a=b.active("1000000",false);}
 CheckoutWorkspaceService.Filter filter(){return new CheckoutWorkspaceService.Filter(a.property(),null,null,null,null,null,null,null,null,null,0,20);}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> d){return (List<Map<String,Object>>)d.get("rows");}
 Map<String,Object> read(){return service.read(f.owner,filter());}
 String phase(){return rows(read()).getFirst().get("stage").toString();}
 long request(){return b.request(a);}
 void manager(String...caps){f.db.sql("INSERT IGNORE INTO property_managers(property_id,manager_id) VALUES(:id,2)").param("id",a.property()).update();for(String cap:caps)f.db.sql("INSERT IGNORE INTO manager_property_capabilities(property_id,manager_id,capability,granted_by) VALUES(:id,2,:cap,1)").param("id",a.property()).param("cap",cap).update();}
 byte[] image(){return Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=");}
 @Test void emptyWorkspaceHasNoInventedRequests(){assertThat(rows(read())).isEmpty();assertThat(((Number)read().get("totalElements")).longValue()).isZero();}
 @Test void requestDoesNotCloseContractOrOccupancy(){request();assertThat(phase()).isEqualTo("SCHEDULE_PENDING");assertThat(f.db.sql("SELECT status FROM contracts WHERE id=:id").param("id",a.contract()).query(String.class).single()).isEqualTo("ACTIVE");assertThat(f.db.sql("SELECT status FROM rooms WHERE id=:id").param("id",a.room()).query(String.class).single()).isEqualTo("NOTICE");}
 @Test void sequentialRequestRetryIsOneSourceAndOneHistory(){var r=new RequestCheckout(a.contract(),LocalDate.now(),"  Agreed return  ");long first=f.inTx(()->b.workflow.request(f.owner,r)).id();assertThat(f.inTx(()->b.workflow.request(f.owner,r)).id()).isEqualTo(first);assertThat(rows(read())).hasSize(1);assertThat(f.db.sql("SELECT COUNT(*) FROM checkout_history WHERE checkout_id=:id AND event_type='REQUESTED'").param("id",first).query(Long.class).single()).isOne();}
 @Test void legacyLifecycleRequestDelegatesToSameWorkflow(){var r=new RequestCheckout(a.contract(),LocalDate.now(),"Same source");long first=f.inTx(()->f.lifecycle.requestCheckout(f.owner,r)).id();assertThat(f.inTx(()->b.workflow.request(f.owner,r)).id()).isEqualTo(first);assertThat(rows(read())).hasSize(1);}
 @Test void concurrentRequestsKeepOneCheckout()throws Exception{var r=new RequestCheckout(a.contract(),LocalDate.now(),"Concurrent return");try(var pool=Executors.newFixedThreadPool(2)){var one=pool.submit(()->f.inTx(()->b.workflow.request(f.owner,r)).id());var two=pool.submit(()->f.inTx(()->b.workflow.request(f.owner,r)).id());assertThat(one.get(20,TimeUnit.SECONDS)).isEqualTo(two.get(20,TimeUnit.SECONDS));}assertThat(rows(read())).hasSize(1);}
 @Test void scheduleAndInspectionAreDerivedPhases(){long id=request();f.run(()->b.workflow.approveSchedule(f.owner,id,new Schedule(LocalDate.now(),b.version(id),"Review terms","Agreement")));assertThat(phase()).isEqualTo("INSPECTION");b.inspect(a,id);assertThat(phase()).isEqualTo("SETTLEMENT");b.approve(a,id,true);assertThat(phase()).isEqualTo("CONFIRMATION");}
 @Test void refundApprovalIsNotCashAndPhaseReflectsPendingPayout(){long id=request();b.inspect(a,id);b.approve(a,id,true);b.apply(a,id);assertThat(phase()).isEqualTo("REFUND");f.run(()->f.ledger.approveRefund(f.owner,a.deposit(),b.refund(id)));assertThat(phase()).isEqualTo("REFUND");assertThat(new com.thangit.boardinghouse.repository.ManagementFinanceRepository(f.db).summary(List.of(a.property()),LocalDate.now().withDayOfMonth(1),LocalDate.now()).get("cashOut")).isZero();}
 @Test void closureKeepsHistoricalResidenceAndOriginalProfile(){long id=request();b.inspect(a,id);b.approve(a,id,true);b.apply(a,id);long ref=b.refund(id);f.run(()->f.ledger.approveRefund(f.owner,a.deposit(),ref));f.run(()->f.ledger.payRefund(f.accountant,a.deposit(),ref,f.key(),f.cash("1000000")));assertThat(phase()).isEqualTo("CLOSE_READY");f.run(()->f.ledger.closeCheckout(f.owner,a.deposit()));assertThat(phase()).isEqualTo("COMPLETED");assertThat(f.db.sql("SELECT COUNT(*) FROM tenant_residences WHERE contract_id=:id AND status='MOVED_OUT'").param("id",a.contract()).query(Long.class).single()).isPositive();assertThat(f.db.sql("SELECT COUNT(*) FROM tenant_profiles WHERE id=:id").param("id",a.profile()).query(Long.class).single()).isOne();}
 @Test void disputedRequestCannotBePresentedAsCompleted(){long id=request();f.run(()->b.workflow.dispute(f.tenant,id,new Dispute("Please review item damage")));assertThat(phase()).isEqualTo("DISPUTED");assertThat((List<?>)f.inTx(()->b.workflow.detail(f.tenant,a.contract())).get("blockers")).isNotEmpty();}
 @Test void projectionDoesNotExposePrivateIdentityOrInternalUnredactedMoney(){request();manager();var row=rows(service.read(manager,filter())).getFirst();assertThat(row).doesNotContainKeys("identity_number","email","phone","source_debt","source_deposit");assertThat(row.get("current_debt")).isNull();assertThat(row.get("held_deposit")).isNull();assertThatThrownBy(()->f.inTx(()->b.workflow.detail(manager,a.contract()))).isInstanceOf(RuntimeException.class);}
 @Test void managerNeedsContractCapabilityForRequest(){manager("FINANCE_READ");assertThatThrownBy(()->f.inTx(()->b.workflow.request(manager,new RequestCheckout(a.contract(),LocalDate.now(),"Unauthorized request")))).isInstanceOf(RuntimeException.class);assertThat(rows(read())).isEmpty();}
 @Test void managerNeedsDepositApprovalForSettlementApproval(){long id=request();b.inspect(a,id);manager("CONTRACT_APPROVE","FINANCE_READ");var preview=f.inTx(()->b.workflow.preview(manager,id));assertThatThrownBy(()->f.run(()->b.workflow.approve(manager,id,new Approval(b.version(id),preview.hash(),"Terms","Review","NONE")))).isInstanceOf(RuntimeException.class);}
 @Test void otherOwnerAndTenantCannotUseWorkspace(){request();assertThatThrownBy(()->service.read(other,filter())).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->service.options(f.tenant)).isInstanceOf(RuntimeException.class);}
 @Test void accountantUsesOnlyAssignedProperties(){request();assertThat(rows(service.read(f.accountant,filter()))).hasSize(1);f.db.sql("DELETE FROM accountant_property_assignments WHERE accountant_id=3 AND property_id=:id").param("id",a.property()).update();assertThatThrownBy(()->service.read(f.accountant,filter())).isInstanceOf(RuntimeException.class);}
 @Test void dateRoomSearchAndPaginationAreServerFilters(){request();var f1=new CheckoutWorkspaceService.Filter(a.property(),null,a.room(),LocalDate.now(),LocalDate.now(),"no-match",null,null,null,null,0,20);assertThat(rows(service.read(f.owner,f1))).isEmpty();assertThat(rows(service.read(f.owner,new CheckoutWorkspaceService.Filter(a.property(),null,null,null,null,null,null,null,null,null,1,1)))).isEmpty();assertThat(rows(service.read(f.owner,new CheckoutWorkspaceService.Filter(a.property(),null,null,LocalDate.now().plusDays(1),null,null,null,null,null,null,0,20)))).isEmpty();}
 @Test void companyFilterDoesNotExpandOwnership(){request();assertThat(rows(service.read(f.owner,new CheckoutWorkspaceService.Filter(a.property(),999999L,null,null,null,null,null,null,null,null,0,20)))).isEmpty();}
 @Test void assignHandoverPersonHasVersionHistoryAndNotification(){long id=request();long before=f.db.sql("SELECT COUNT(*) FROM notifications WHERE user_id=5").query(Long.class).single();f.run(()->service.assign(f.owner,id,new CheckoutWorkspaceService.Assignment(1,0,LocalDateTime.now().plusDays(1),"Agreed inspection")));assertThat(((Number)rows(read()).getFirst().get("assignee_id")).longValue()).isOne();assertThat(f.db.sql("SELECT COUNT(*) FROM notifications WHERE user_id=5").query(Long.class).single()).isEqualTo(before+1);assertThatThrownBy(()->f.run(()->service.assign(f.owner,id,new CheckoutWorkspaceService.Assignment(1,0,LocalDateTime.now().plusDays(1),"Stale")))).isInstanceOf(RuntimeException.class);}
 @Test void cannotAssignForeignStaff(){long id=request();assertThatThrownBy(()->f.run(()->service.assign(f.owner,id,new CheckoutWorkspaceService.Assignment(4,0,LocalDateTime.now().plusDays(1),"Foreign")))).isInstanceOf(RuntimeException.class);}
 @Test void rescheduleClearsPreviousScheduleApproval(){long id=request();f.run(()->b.workflow.approveSchedule(f.owner,id,new Schedule(LocalDate.now(),0L,"Reviewed","Agreement")));f.run(()->b.workflow.schedule(f.owner,id,new Schedule(LocalDate.now().plusDays(1),1L,"Changed plan","Agreement 2")));assertThat(phase()).isEqualTo("SCHEDULE_PENDING");assertThat(b.co(id).get("confirmed_date")).isNull();}
 @Test void chargeRetryDoesNotInvalidateVersionTwice(){long id=request();var r=new ChargeRequest("DAMAGE-1","DAMAGE","Confirmed physical fault",new BigDecimal("100"),"FILE-1","Review needed",null);long first=f.inTx(()->b.workflow.proposeCharge(f.owner,id,r));long version=b.version(id);assertThat(f.inTx(()->b.workflow.proposeCharge(f.owner,id,r))).isEqualTo(first);assertThat(b.version(id)).isEqualTo(version);assertThat(f.balance(a.deposit())).isEqualByComparingTo("1000000");}
 @Test void changedChargeCannotReuseEvidenceKey(){long id=request();f.run(()->b.workflow.proposeCharge(f.owner,id,new ChargeRequest("DAMAGE-1","DAMAGE","Fault",new BigDecimal("100"),"FILE-1","Review",null)));assertThatThrownBy(()->f.run(()->b.workflow.proposeCharge(f.owner,id,new ChargeRequest("DAMAGE-1","DAMAGE","Fault",new BigDecimal("200"),"FILE-1","Review",null)))).isInstanceOf(RuntimeException.class);}
 @Test void privateEvidenceRetryKeepsOneFileAndNoMoneyEvent(){long id=request();String key=f.key();long file=f.inTx(()->files.upload(f.tenant,id,key,"INSPECTION",null,"before.png","image/png",image()));assertThat(f.inTx(()->files.upload(f.tenant,id,key,"INSPECTION",null,"before.png","image/png",image()))).isEqualTo(file);assertThat(files.list(f.owner,id)).hasSize(1);assertThat(f.inTx(()->files.file(f.tenant,id,file)).bytes()).isEqualTo(image());assertThat(f.balance(a.deposit())).isEqualByComparingTo("1000000");}
 @Test void privateEvidenceCannotCrossOwnerTenantOrCheckout(){long id=request();long file=f.inTx(()->files.upload(f.owner,id,f.key(),"UTILITY",null,"meter.png","image/png",image()));assertThatThrownBy(()->files.list(other,id)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->files.file(new AuthenticatedUser(4L,"other",RoleCode.TENANT),id,file)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->files.file(f.owner,id,file+9999)).isInstanceOf(RuntimeException.class);}
 @Test void fakeMimeAndForeignDisputeAreRejected(){long id=request();assertThatThrownBy(()->f.inTx(()->files.upload(f.owner,id,f.key(),"UTILITY",null,"meter.txt","text/plain",image()))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->f.inTx(()->files.upload(f.owner,id,f.key(),"DISPUTE",999999L,"meter.png","image/png",image()))).isInstanceOf(RuntimeException.class);}
 @Test void evidenceIsAppendOnlyAfterClosure(){long id=request();b.inspect(a,id);b.approve(a,id,true);b.apply(a,id);long refund=b.refund(id);f.run(()->f.ledger.approveRefund(f.owner,a.deposit(),refund));f.run(()->f.ledger.payRefund(f.accountant,a.deposit(),refund,f.key(),f.cash("1000000")));f.run(()->f.ledger.closeCheckout(f.owner,a.deposit()));assertThatThrownBy(()->f.inTx(()->files.upload(f.owner,id,f.key(),"HANDOVER",null,"after.png","image/png",image()))).isInstanceOf(RuntimeException.class);}
 @Test void approvedDocumentUsesOnlyScopedSnapshot(){long id=request();b.inspect(a,id);b.approve(a,id,true);assertThat((List<?>)f.inTx(()->b.workflow.detail(f.owner,a.contract())).get("approvedLines")).isNotNull();assertThatThrownBy(()->f.inTx(()->b.workflow.document(other,a.contract()))).isInstanceOf(RuntimeException.class);}
 @Test void changingConfirmedDateRequiresFreshInspection(){long id=request();b.inspect(a,id);long version=b.version(id);assertThatThrownBy(()->f.run(()->b.workflow.approveSchedule(f.owner,id,new Schedule(LocalDate.now().plusDays(1),version,"Changed date","Agreement")))).isInstanceOf(RuntimeException.class);assertThat(b.version(id)).isEqualTo(version);}
 @Test void unknownMimeAndUnknownBytesCannotBecomeEvidence(){long id=request();assertThatThrownBy(()->f.inTx(()->files.upload(f.owner,id,f.key(),"INSPECTION",null,"invalid",null,new byte[]{1,2,3}))).isInstanceOf(RuntimeException.class);assertThat(files.list(f.owner,id)).isEmpty();}
 @Test void requesterIsNotInventedAsHandoverAssignee(){request();assertThat(rows(read()).getFirst().get("assignee_id")).isNull();assertThat(rows(read()).getFirst().get("assignee_name")).isNull();}
 @Test void assignedManagerNameAndFilterUseActualAssignee(){long id=request();manager("CONTRACT_APPROVE");f.run(()->service.assign(f.owner,id,new CheckoutWorkspaceService.Assignment(2,0,LocalDateTime.now().plusDays(1),"Manager inspection")));var row=rows(read()).getFirst();assertThat(((Number)row.get("assignee_id")).longValue()).isEqualTo(2);assertThat(row.get("assignee_name")).isEqualTo(f.db.sql("SELECT full_name FROM users WHERE id=2").query(String.class).single());assertThat(rows(service.read(f.owner,new CheckoutWorkspaceService.Filter(a.property(),null,null,null,null,null,null,null,2L,null,0,20)))).hasSize(1);}
}
